  homeRoute: '/dashboard',
};

/**
 * Validates JWT token format and expiration
 */
function validateJWT(token: string): JWTPayload | null {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) {
      throw new Error('Invalid JWT format');
    }

    const base64Payload = parts[1];
    const payload = JSON.parse(atob(base64Payload)) as JWTPayload;

    // Check expiration
    const currentTime = Math.floor(Date.now() / 1000);
    if (payload.exp && payload.exp < currentTime) {
      return null;
    }

    return payload;
  } catch (error) {
    console.error('JWT validation error:', error);
    return null;
  }
}

/**
 * Checks if a route matches a pattern (supports wildcards)
 */
function matchesRoute(pattern: string, pathname: string): boolean {
  if (pattern.includes('*')) {
    const regex = new RegExp(pattern.replace(/\*/g, '.*'));
    return regex.test(pathname);
  }
  return pathname === pattern || pathname.startsWith(pattern + '/');
}

/**
 * Determines if a route requires authentication
 */
function requiresAuth(pathname: string): boolean {
  // Check if it's a public route
  const isPublicRoute = config.publicRoutes.some(route => 
    matchesRoute(route, pathname)
  );

  if (isPublicRoute) return false;

  // Check if it's a protected route
  const isProtectedRoute = config.protectedRoutes.some(route => 
    matchesRoute(route, pathname)
  );

